def import_events(db,tenant,events):
    inserted=0
    with db:
        db.execute('insert into balances values(?,0) on conflict(tenant) do nothing',(tenant,))
        for key,amount in events:
            if type(amount) is not int or amount<=0:raise ValueError('invalid amount')
            row=db.execute('select amount from events where tenant=? and id=?',(tenant,key)).fetchone()
            if row is not None:
                if row[0]!=amount:raise ValueError('conflicting replay')
                continue
            db.execute('insert into events values(?,?,?)',(tenant,key,amount))
            db.execute('update balances set value=value+? where tenant=?',(amount,tenant));inserted+=1
    return inserted

