import asyncio
async def run_jobs(jobs,call,workers,retries):
    if workers<1 or retries<0:raise ValueError('invalid policy')
    unique={}
    for key,payload in jobs:
        if key in unique and unique[key]!=payload:raise ValueError('conflicting job')
        unique[key]=payload
    results={};pending=iter(unique.items())
    async def worker():
        for key,payload in pending:
            for attempt in range(retries+1):
                try:results[key]=await call(payload);break
                except OSError:
                    if attempt==retries:raise
    async with asyncio.TaskGroup() as group:
        for _ in range(min(workers,len(unique))):group.create_task(worker())
    return {key:results[key] for key in unique}

