import math
def regression_experiment(train,validation,test,penalties):
    for xs,ys in [train,validation,test]:
        if not xs or len(xs)!=len(ys) or any(not math.isfinite(v) for v in list(xs)+list(ys)):raise ValueError('invalid dataset')
    if not penalties or any(not math.isfinite(v) or v<0 for v in penalties):raise ValueError('invalid penalty')
    xs,ys=train;mean=sum(xs)/len(xs);scale=(sum((x-mean)**2 for x in xs)/len(xs))**.5 or 1.0
    z=[(x-mean)/scale for x in xs];b=sum(ys)/len(ys);numerator=sum(x*(y-b) for x,y in zip(z,ys));den=sum(x*x for x in z);models=[]
    for penalty in penalties:
        w=numerator/(den+penalty) if den+penalty else 0.0
        vx,vy=validation;error=sum((b+w*(x-mean)/scale-y)**2 for x,y in zip(vx,vy))/len(vx);models.append((error,penalty,w))
    error,penalty,w=min(models);tx,ty=test;pred=[b+w*(x-mean)/scale for x in tx]
    return dict(mean=mean,scale=scale,w=w,b=b,penalty=penalty,validation_mse=error,test_mse=sum((p-y)**2 for p,y in zip(pred,ty))/len(ty),test_predictions=pred)

