import math
def delayed_report(predictions,outcomes):
    labels={}
    for key,label in outcomes:
        if key in labels or type(label) is not int or label not in (0,1):raise ValueError('invalid outcome')
        labels[key]=label
    seen=set();groups={}
    for key,version,p in predictions:
        if key in seen or not math.isfinite(p) or not 0<=p<=1:raise ValueError('invalid prediction')
        seen.add(key);g=groups.setdefault(version,{'predictions':0,'matched':0,'total':0.0});g['predictions']+=1
        if key in labels:g['matched']+=1;g['total']+=(p-labels[key])**2
    return {v:{'predictions':g['predictions'],'matched':g['matched'],'brier':g['total']/g['matched'] if g['matched'] else None} for v,g in groups.items()}

