def build_context(docs,tenant,query,budget):
    if budget<0:raise ValueError('negative budget')
    allowed=[d for d in docs if d['tenant']==tenant];ids=[d['id'] for d in allowed]
    if len(set(ids))!=len(ids):raise ValueError('duplicate document')
    q=set(query);ranked=[]
    for d in allowed:
        tokens=set(d['tokens']);union=q|tokens;score=len(q&tokens)/len(union) if union else 0
        if score>0:ranked.append((-score,d['id'],d))
    evidence=[];used=0
    for _,key,d in sorted(ranked,key=lambda r:(r[0],r[1])):
        size=len(d['tokens'])
        if used+size<=budget:evidence.append({'id':key,'tokens':list(d['tokens'])});used+=size
    return {'ids':[d['id'] for d in evidence],'tokens_used':used,'evidence':evidence}

