import hashlib,hmac,json
def execute_approved(call,tenant,scopes,policy,approved_digest,receipts,perform):
    tool=call.get('tool')
    if tool not in policy or call.get('tenant')!=tenant or policy[tool] not in scopes:raise PermissionError('not authorized')
    raw=json.dumps({'tool':tool,'args':call['args']},sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode();identity=hashlib.sha256(raw).hexdigest()
    if not hmac.compare_digest(identity,approved_digest):raise PermissionError('approval mismatch')
    key=(tenant,call['id'])
    if key in receipts:
        previous,result=receipts[key]
        if previous!=identity:raise ValueError('conflicting replay')
        return result
    result=perform(tool,call['args']);receipts[key]=(identity,result);return result

